DROP VIEW IF EXISTS library_la_potencia_plegaria_investigative_audit_v1;
DROP VIEW IF EXISTS library_la_potencia_plegaria_investigative_search_v1;
CREATE VIEW library_la_potencia_plegaria_investigative_search_v1 AS
SELECT p.pdf_page,p.page_status,s.document_part,s.structural_status,z.zone_type,NULL::text note_number,NULL::text surface_form,NULL::text normalized_reference_name,NULL::text resolution_decision,z.text_quote quote,'fine_zone'::text search_record_type,'validated_zone'::text evidence_level FROM library_la_potencia_plegaria_pages_v1 p JOIN library_la_potencia_plegaria_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page JOIN library_la_potencia_plegaria_fine_zones_v1 z ON z.document_id=p.document_id AND z.pdf_page=p.pdf_page WHERE z.validation_status='validated'
UNION ALL SELECT p.pdf_page,p.page_status,s.document_part,s.structural_status,NULL,n.visible_note_number,NULL,NULL,NULL,n.text_quote,'note_source_unit','validated_note' FROM library_la_potencia_plegaria_pages_v1 p JOIN library_la_potencia_plegaria_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page JOIN library_la_potencia_plegaria_note_source_units_v1 n ON n.document_id=p.document_id AND n.pdf_page=p.pdf_page
UNION ALL SELECT p.pdf_page,p.page_status,s.document_part,s.structural_status,NULL,NULL,r.surface_form,r.normalized_reference_name,NULL,r.text_quote,'nominal_reference','validated_nominal_reference' FROM library_la_potencia_plegaria_pages_v1 p JOIN library_la_potencia_plegaria_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page JOIN library_la_potencia_plegaria_nominal_references_v1 r ON r.document_id=p.document_id AND r.pdf_page=p.pdf_page;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_investigative_audit_v1 AS SELECT * FROM library_la_potencia_plegaria_investigative_search_v1 WHERE search_record_type <> 'nominal_reference' OR surface_form IS NOT NULL;
